import { readFileSync } from 'node:fs';
import { ok, fail } from './result.js';

const CUSTOMERS = JSON.parse(readFileSync(new URL('../data/customers.json', import.meta.url), 'utf8'));

export const TIER_DISCOUNTS = {
  gold: 5,
  silver: 2.5,
  standard: 0,
};

/**
 * Normalize a customer ID: trim whitespace and convert to uppercase.
 * @param {string} id
 * @returns {string}
 */
export function normalizeId(id) {
  return String(id).trim().toUpperCase();
}

/**
 * All customers: { id, name, email, country, tier }.
 */
export function listCustomers() {
  return CUSTOMERS.map((c) => ({ ...c }));
}

/**
 * One customer by id.
 * @param {string} id
 */
export function getCustomer(id) {
  const normalizedId = normalizeId(id);
  const c = CUSTOMERS.find((x) => x.id === normalizedId);
  return c ? ok({ ...c }) : fail('CUSTOMER_NOT_FOUND');
}

/**
 * Check a customer record before it is stored.
 * @param {{ id?: string, name?: string, email?: string }} c
 */
export function validateCustomer(c) {
  if (!c || !c.id || !c.name || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(c.email ?? '')) return fail('CUSTOMER_INVALID');
  return ok({ ...c });
}

/**
 * Merge two customers: fromId's customer is deleted, all its invoices reassigned to intoId.
 * @param {any[]} customers
 * @param {any[]} invoices
 * @param {string} fromId
 * @param {string} intoId
 * @returns {{ ok: true, value: { customers: any[], invoices: any[] } } | { ok: false, error: string }}
 */
export function mergeCustomers(customers, invoices, fromId, intoId) {
  const normalizedFrom = normalizeId(fromId);
  const normalizedInto = normalizeId(intoId);

  if (normalizedFrom === normalizedInto) {
    return fail('SAME_CUSTOMER');
  }

  const fromExists = customers.some((c) => c.id === normalizedFrom);
  const intoExists = customers.some((c) => c.id === normalizedInto);

  if (!fromExists || !intoExists) {
    return fail('CUSTOMER_NOT_FOUND');
  }

  const newCustomers = customers.filter((c) => c.id !== normalizedFrom).map((c) => ({ ...c }));
  const newInvoices = invoices.map((inv) =>
    inv.customerId === normalizedFrom ? { ...inv, customerId: normalizedInto } : { ...inv }
  );

  return ok({ customers: newCustomers, invoices: newInvoices });
}

/** Every error code the project returns, with a one-line message. Codes are UPPER_SNAKE_CASE. */
export const ERRORS = {
  AMOUNT_INVALID: 'Amount must be a whole, positive number of cents.',
  CUSTOMER_INVALID: 'A customer needs an id, a name and a valid email.',
  CUSTOMER_NOT_FOUND: 'No customer with that id.',
  UNKNOWN_SKU: 'No product with that SKU in the catalogue.',
  DATE_INVALID: 'Invoice date must be a real date in YYYY-MM-DD format.',
  NO_LINES: 'Invoice must have at least one line item.',
  QTY_INVALID: 'Line item quantity must be a positive integer.',
  NOT_DRAFT: 'Can only modify invoices with status "draft".',
  LINE_NOT_FOUND: 'That SKU is not on this invoice.',
  DISCOUNT_INVALID: 'Discount percent must be a number between 0 and 100.',
  NOT_ISSUED: 'Invoice must be issued or partially paid to record a payment.',
  OVERPAYMENT: 'Payment amount exceeds the balance due.',
  TERMS_INVALID: 'Payment terms must be NET14, NET30, or EOM.',
  VOUCHER_EXISTS: 'Invoice already has a voucher applied.',
  CREDIT_TOO_HIGH: 'Credit note amount exceeds the invoice total.',
  UNKNOWN_CURRENCY: 'Currency code not recognized. Use EUR, USD, or GBP.',
  SAME_CUSTOMER: 'Cannot merge a customer with themselves.',
};

/**
 * The message for an error code.
 * @param {string} code
 * @returns {string}
 */
export function message(code) {
  return ERRORS[code] ?? 'Unknown error.';
}
